INSERT INTO bench_seq SELECT n FROM (SELECT a.d + b.d*10 + c.d*100 + d.d*1000 + e.d*10000 + f.d*100000 AS n FROM (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a, (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b, (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) c, (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) d, (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) e, (SELECT 0 d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) f) digits WHERE n < 25001;
INSERT INTO nagios_server (id, uid, name, localhost, is_default, ns_activate) VALUES (100000, 100000, 'bench-poller', '0', 0, '1');
INSERT INTO host (host_id, host_name, host_alias, host_register, host_activate) SELECT 900000+n, CONCAT('bench-htpl-', n), 'bench', '0', '1' FROM bench_seq WHERE n < 5;
INSERT INTO host (host_id, host_name, host_alias, host_address, host_register, host_activate) SELECT 1000000+n, CONCAT('bench-host-', n), 'bench', '127.0.0.1', '1', '1' FROM bench_seq WHERE n < 2500;
INSERT INTO host_template_relation (host_host_id, host_tpl_id, `order`) SELECT 1000000+n, 900000+(n % 5), 1 FROM bench_seq WHERE n < 2500;
INSERT INTO ns_host_relation (nagios_server_id, host_host_id) SELECT 100000, 1000000+n FROM bench_seq WHERE n < 2500;
INSERT INTO service_categories (sc_id, sc_name, sc_description, sc_activate) SELECT 100000+n, CONCAT('bench-sc-', n), 'bench', '1' FROM bench_seq WHERE n < 5;
INSERT INTO service (service_id, service_description, service_register, service_activate) SELECT 8000000+n, CONCAT('bench-stpl-', n), '0', '1' FROM bench_seq WHERE n < 20;
INSERT INTO service_categories_relation (service_service_id, sc_id) SELECT 8000000+n, 100000+(n % 5) FROM bench_seq WHERE n < 20;
INSERT INTO service (service_id, service_description, service_template_model_stm_id, service_register, service_activate) SELECT 9000000+n, CONCAT('bench-svc-', n % 10), 8000000+(n % 20), '1', '1' FROM bench_seq WHERE n < 25000;
INSERT INTO host_service_relation (host_host_id, service_service_id) SELECT 1000000+(n DIV 10), 9000000+n FROM bench_seq WHERE n < 25000;
INSERT INTO hostgroup (hg_id, hg_name, hg_alias, hg_activate) SELECT 100000+n, CONCAT('bench-hg-', n), 'bench', '1' FROM bench_seq WHERE n < 125;
INSERT INTO hostgroup_relation (hostgroup_hg_id, host_host_id) SELECT 100000+(n % 125), 1000000+n FROM bench_seq WHERE n < 2500;
INSERT INTO hostgroup_relation (hostgroup_hg_id, host_host_id) SELECT 100000+((n + 62) % 125), 1000000+n FROM bench_seq WHERE n < 2500 AND n % 2 = 0;
INSERT INTO servicegroup (sg_id, sg_name, sg_alias, sg_activate) SELECT 100000+n, CONCAT('bench-sg-', n), 'bench', '1' FROM bench_seq WHERE n < 50;
INSERT INTO servicegroup_relation (host_host_id, service_service_id, servicegroup_sg_id) SELECT 1000000+n, 9000000+n*10, 100000+(n % 50) FROM bench_seq WHERE n < 2500;
INSERT INTO hostcategories (hc_id, hc_name, hc_alias, hc_activate) SELECT 100000+n, CONCAT('bench-hc-', n), 'bench', '1' FROM bench_seq WHERE n < 10;
INSERT INTO hostcategories_relation (hostcategories_hc_id, host_host_id) SELECT 100000+n, 900000+n FROM bench_seq WHERE n < 5;
INSERT INTO hostcategories_relation (hostcategories_hc_id, host_host_id) SELECT 100000+5+(n % 5), 1000000+n FROM bench_seq WHERE n < 2500 AND n % 10 = 0;
INSERT INTO contact (contact_id, contact_name, contact_alias, contact_email, contact_activate, contact_oreon, contact_admin, contact_register) SELECT 100000+n, CONCAT('bench-contact-', n), CONCAT('bench-contact-', n), 'bench@localhost', '1', '1', '0', 1 FROM bench_seq WHERE n < 250;
INSERT INTO contactgroup (cg_id, cg_name, cg_alias, cg_activate, cg_type) SELECT 100000+n, CONCAT('bench-cg-', n), 'bench', '1', 'local' FROM bench_seq WHERE n < 50;
INSERT INTO contactgroup_contact_relation (contact_contact_id, contactgroup_cg_id) SELECT 100000+n, 100000+(n % 50) FROM bench_seq WHERE n < 250;
INSERT INTO acl_groups (acl_group_id, acl_group_name, acl_group_alias, acl_group_changed, acl_group_activate, cloud_specific, all_contacts, all_contact_groups) SELECT 100000+n, CONCAT('bench-ag-', n), 'bench', 1, '1', 0, 0, 0 FROM bench_seq WHERE n < 20;
INSERT INTO acl_group_contacts_relations (contact_contact_id, acl_group_id) SELECT 100000+n, 100000+(n % 20) FROM bench_seq WHERE n < 250;
INSERT INTO acl_group_contactgroups_relations (cg_cg_id, acl_group_id) SELECT 100000+(n % 50), 100000+n FROM bench_seq WHERE n < 20;
INSERT INTO acl_resources (acl_res_id, acl_res_name, acl_res_alias, acl_res_activate, changed, locked, cloud_specific, all_image_folders) SELECT 100000+n, CONCAT('bench-res-', n), 'bench', '1', 1, 0, 0, 0 FROM bench_seq WHERE n < 40;
INSERT INTO acl_res_group_relations (acl_res_id, acl_group_id, `order`) SELECT 100000+n, 100000+(n DIV 2), 0 FROM bench_seq WHERE n < 40;
INSERT INTO acl_resources_hg_relations (hg_hg_id, acl_res_id) SELECT 100000+((r.n * 12 + k.n) % 125), 100000+r.n FROM bench_seq r JOIN bench_seq k ON k.n < 12 WHERE r.n < 40 AND (r.n % 10 < 4 OR r.n % 10 >= 8);
INSERT INTO acl_resources_host_relations (host_host_id, acl_res_id) SELECT 1000000+((r.n * 125 + k.n) % 2500), 100000+r.n FROM bench_seq r JOIN bench_seq k ON k.n < 125 WHERE r.n < 40 AND r.n % 10 IN (4, 5);
INSERT INTO acl_resources_hostex_relations (host_host_id, acl_res_id) SELECT 1000000+((r.n * 125 + k.n) % 2500), 100000+r.n FROM bench_seq r JOIN bench_seq k ON k.n < 125 AND k.n % 10 = 0 WHERE r.n < 40 AND r.n % 10 IN (4, 5);
INSERT INTO acl_resources_sg_relations (sg_id, acl_res_id) SELECT 100000+((r.n * 5 + k.n) % 50), 100000+r.n FROM bench_seq r JOIN bench_seq k ON k.n < 5 WHERE r.n < 40 AND r.n % 10 IN (6, 7);
INSERT INTO acl_resources_hc_relations (hc_id, acl_res_id) SELECT 100000+(n % 10), 100000+n FROM bench_seq WHERE n < 40 AND n % 10 = 8;
INSERT INTO acl_resources_sc_relations (sc_id, acl_res_id) SELECT 100000+(n % 5), 100000+n FROM bench_seq WHERE n < 40 AND n % 10 = 9;
